pothesis)\n- **1F1B, 1F1B-I \u0914\u0930 ZB-1p** \u092e\u0947\u0902 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u092c\u092c\u0932 \u0926\u0930 \u0938\u0940\u0927\u0947 \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a \u0938\u0902\u0916\u094d\u092f\u093e ($m$) \u0915\u0947 \u0935\u094d\u092f\u0941\u0924\u094d\u0915\u094d\u0930\u092e\u093e\u0928\u0941\u092a\u093e\u0924\u0940 \u0939\u094b\u0924\u0940 \u0939\u0948\u0964 \u0905\u0924\u0903 \u091c\u0948\u0938\u0947-\u091c\u0948\u0938\u0947 $m$ \u092c\u0922\u093c\u0924\u093e \u0939\u0948, \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u092e\u0947\u0902 \u0932\u0917\u093e\u0924\u093e\u0930 \u0914\u0930 \u0909\u0932\u094d\u0932\u0947\u0916\u0928\u0940\u092f \u0938\u0941\u0927\u093e\u0930 \u0939\u094b\u0924\u093e \u0939\u0948\u0964\n- **ZB-2p** \u092a\u094d\u0930\u0924\u093f \u0921\u093f\u0935\u093e\u0907\u0938 \u0926\u094b \u0935\u0930\u094d\u091a\u0941\u0905\u0932 \u091a\u0902\u0915\u094d\u0938 (2-partition) \u0914\u0930 \u092c\u0948\u0915\u0935\u0930\u094d\u0921 \u092a\u093e\u0938 \u0915\u094b \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0928 \u0917\u094d\u0930\u0947\u0921\u093f\u090f\u0902\u091f ($B$) \u090f\u0935\u0902 \u0935\u0947\u091f \u0917\u094d\u0930\u0947\u0921\u093f\u090f\u0902\u091f ($W$) \u092e\u0947\u0902 \u0935\u093f\u092d\u093e\u091c\u093f\u0924 \u0915\u0930\u0915\u0947 \u0936\u0947\u0921\u094d\u092f\u0942\u0932 \u0915\u0930\u0924\u093e \u0939\u0948\u0964 \u0907\u0938\u0915\u0947 \u092a\u0930\u093f\u0923\u093e\u092e\u0938\u094d\u0935\u0930\u0942\u092a, ZB-2p \u0915\u092e \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a ($m \\approx p$) \u092a\u0930 \u092d\u0940 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u092c\u092c\u0932 \u0915\u094b \u0932\u0917\u092d\u0917 \u0936\u0942\u0928\u094d\u092f \u0915\u0930 \u0926\u0947\u0924\u093e \u0939\u0948 \u0914\u0930 \u092c\u0939\u0941\u0924 \u0915\u092e $m$ \u092a\u0930 \u092d\u0940 \u0905\u0927\u093f\u0915\u0924\u092e \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u092c\u0928\u093e\u090f \u0930\u0916\u0924\u093e \u0939\u0948\u0964\n\n### 1.2 \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u092c\u092c\u0932 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 (Theoretical Bubble Analysis)\n\u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0938\u094d\u091f\u0947\u091c\u0947\u0938 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e $p$ \u0914\u0930 \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e $m$ \u0915\u0947 \u0932\u093f\u090f \u0906\u0926\u0930\u094d\u0936 \u092c\u092c\u0932 \u0905\u0928\u0941\u092a\u093e\u0924 ($Bubble\\_Rate$):\n1. **1F1B (\u092e\u093e\u0928\u0915)**:\n   $$\\text{Bubble Rate}_{1F1B} = \\frac{p - 1}{m}$$\n   *\u0928\u093f\u0939\u093f\u0924\u093e\u0930\u094d\u0925*: \u092f\u0926\u093f $m = p$, \u0924\u094b \u092c\u092c\u0932 $\\approx 87.5\\%$ (\u091c\u092c $p=8$); $m=64$ \u0939\u094b\u0928\u0947 \u092a\u0930 \u092f\u0939 \u0918\u091f\u0915\u0930 $\\approx 10.9\\%$ \u0930\u0939 \u091c\u093e\u0924\u093e \u0939\u0948\u0964 \u0905\u0924\u0903 $m$ \u092c\u0922\u093c\u093e\u0928\u0947 \u092a\u0930 \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u0924\u0947\u091c\u0940 \u0938\u0947 \u092c\u0922\u093c\u0924\u093e \u0939\u0948\u0964\n2. **1F1B-I (\u0907\u0902\u091f\u0930\u0932\u0940\u0935\u094d\u0921, $v=2$)**:\n   $$\\text{Bubble Rate}_{1F1B-I} = \\frac{p - 1}{v \\cdot m} = \\frac{p - 1}{2m}$$\n   *\u0928\u093f\u0939\u093f\u0924\u093e\u0930\u094d\u0925*: 1F1B \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u092c\u092c\u0932 \u0906\u0927\u093e \u0939\u094b\u0924\u093e \u0939\u0948, \u0932\u0947\u0915\u093f\u0928 \u092b\u093f\u0930 \u092d\u0940 $m$ \u092a\u0930 \u0928\u093f\u0930\u094d\u092d\u0930 \u0915\u0930\u0924\u093e \u0939\u0948 \u0914\u0930 $m$ \u092c\u0922\u093c\u0928\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u092c\u0947\u0939\u0924\u0930 \u0939\u094b\u0924\u093e \u0939\u0948\u0964\n3. **ZB-1p (1-\u092a\u093e\u0930\u094d\u091f\u0940\u0936\u0928 \u091c\u093c\u0940\u0930\u094b \u092c\u092c\u0932)**:\n   - \u092c\u0948\u0915\u0935\u0930\u094d\u0921 \u092a\u093e\u0938 \u0915\u094b $B$ (\u0907\u0928\u092a\u0941\u091f \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0928 \u0917\u094d\u0930\u0947\u0921\u093f\u090f\u0902\u091f\u094d\u0938) \u0914\u0930 $W$ (\u0935\u0947\u091f \u0917\u094d\u0930\u0947\u0921\u093f\u090f\u0902\u091f\u094d\u0938) \u092e\u0947\u0902 \u0935\u093f\u092d\u093e\u091c\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948, \u091c\u0939\u093e\u0901 $T_F \\approx T_B \\approx T_W$\u0964\n   $$\\text{Bubble Rate}_{ZB-1p} \\approx \\frac{p - 1}{3m}$$\n   *\u0928\u093f\u0939\u093f\u0924\u093e\u0930\u094d\u0925*: \u092c\u092c\u0932 1F1B \u0915\u093e \u0932\u0917\u092d\u0917 \u090f\u0915-\u0924\u093f\u0939\u093e\u0908 \u0939\u094b\u0924\u093e \u0939\u0948, \u0932\u0947\u0915\u093f\u0928 \u0915\u092e $m$ \u092a\u0930 \u092c\u092c\u0932 \u092e\u094c\u091c\u0942\u0926 \u0930\u0939\u0924\u093e \u0939\u0948 \u0914\u0930 $m$ \u092c\u0922\u093c\u0928\u0947 \u092a\u0930 \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u092c\u0922\u093c\u0924\u093e \u0939\u0948\u0964\n4. **ZB-2p (2-\u092a\u093e\u0930\u094d\u091f\u0940\u0936\u0928 \u091c\u093c\u0940\u0930\u094b \u092c\u092c\u0932)**:\n   - 2 \u092e\u0949\u0921\u0932 \u091a\u0902\u0915\u094d\u0938 \u092a\u094d\u0930\u0924\u093f \u0921\u093f\u0935\u093e\u0907\u0938 + $B/W$ \u0935\u093f\u092d\u093e\u091c\u0928\u0964 \u091c\u092c $m \\ge p$, \u0924\u094b \u0938\u092d\u0940 \u0906\u0907\u0921\u0932 \u0938\u094d\u0932\u0949\u091f\u094d\u0938 \u0915\u094b $W$ \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928 \u0926\u094d\u0935\u093e\u0930\u093e \u092d\u0930 \u0926\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948:\n   $$\\text{Bubble Rate}_{ZB-2p} \\approx 0 \\quad (\\text{for } m \\ge p)$$\n   *\u0928\u093f\u0939\u093f\u0924\u093e\u0930\u094d\u0925*: \u0915\u092e $m$ (\u091c\u0948\u0938\u0947 $m = p$) \u092a\u0930 \u092d\u0940 \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u0905\u092a\u0928\u0947 \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0909\u091a\u094d\u091a\u0924\u092e \u0938\u094d\u0924\u0930 (peak throughput) \u0915\u0947 \u0928\u093f\u0915\u091f \u092a\u0939\u0941\u0901\u091a \u091c\u093e\u0924\u093e \u0939\u0948\u0964\n\n---\n\n## 2. \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0938\u0947\u091f\u0905\u092a \u090f\u0935\u0902 \u0939\u093e\u0930\u094d\u0921\u0935\u0947\u092f\u0930 \u0935\u093f\u0928\u093f\u0930\u094d\u0926\u0947\u0936 (Experimental Setup & System Specification)\n\n| \u0918\u091f\u0915 (Component) | \u0935\u093f\u0928\u093f\u0930\u094d\u0926\u0947\u0936 (Specification) | \u0935\u093f\u0935\u0930\u0923 / \u0914\u091a\u093f\u0924\u094d\u092f |\n| :--- | :--- | :--- |\n| **\u092e\u0949\u0921\u0932 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930** | GPT/LLaMA-\u0936\u0948\u0932\u0940 \u091f\u094d\u0930\u093e\u0902\u0938\u092b\u0949\u0930\u094d\u092e\u0930 | 7B \u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930\u094d\u0938 (32 \u0932\u0947\u092f\u0930\u094d\u0938, \u0939\u093f\u0921\u0928 \u0938\u093e\u0907\u091c $d=4096$, 32 \u0905\u091f\u0947\u0902\u0936\u0928 \u0939\u0947\u0921\u094d\u0938) |\n| **\u0938\u0940\u0915\u094d\u0935\u0947\u0902\u0938 \u0932\u0902\u092c\u093e\u0908 ($s$)** | 2048 \u091f\u094b\u0915\u0928 | \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u0923 \u0915\u0949\u0928\u094d\u092b\u093c\u093f\u0917\u0930\u0947\u0936\u0928 |\n| **\u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0938\u094d\u091f\u0947\u091c\u0947\u0938 ($p$)** | 8 \u0938\u094d\u091f\u0947\u091c\u0947\u0938 ($p=8$) | 1 \u0928\u094b\u0921 \u092a\u0930 $8 \\times$ NVIDIA A100 (80GB SXM4) \u092f\u093e H100 GPU |\n| **\u0907\u0902\u091f\u0930\u0915\u0928\u0947\u0915\u094d\u091f** | NVLink (600 GB/s \u0926\u094d\u0935\u093f\u0926\u093f\u0936\u0940\u092f) | \u0928\u094d\u092f\u0942\u0928\u0924\u092e \u0938\u0902\u091a\u093e\u0930 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0924\u093e\u0915\u093f \u092c\u092c\u0932 \u092a\u094d\u0930\u092d\u093e\u0935 \u0936\u0941\u0926\u094d\u0927 \u0930\u0942\u092a \u0938\u0947 \u092e\u093e\u092a\u093e \u091c\u093e \u0938\u0915\u0947 |\n| **\u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a \u0906\u0915\u093e\u0930 ($b$)** | $b = 1$ (\u092a\u094d\u0930\u0924\u093f \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a \u0938\u0948\u0902\u092a\u0932\u094d\u0938) | \u0928\u093f\u0936\u094d\u091a\u093f\u0924, \u0924\u093e\u0915\u093f \u092a\u094d\u0930\u0924\u093f-\u0915\u0930\u094d\u0928\u0947\u0932 \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928 \u0938\u092e\u092f \u0938\u094d\u0925\u093f\u0930 \u0930\u0939\u0947 |\n| **\u092a\u094d\u0930\u093f\u0938\u093f\u091c\u0928** | BF16 / FP16 Mixed Precision | \u0906\u0927\u0941\u0928\u093f\u0915 \u090f\u0932\u090f\u0932\u090f\u092e \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u0923 \u092e\u093e\u0928\u0915 |\n| **\u0938\u0949\u092b\u094d\u091f\u0935\u0947\u092f\u0930 \u0938\u094d\u091f\u0948\u0915** | PyTorch + CUDA 12.x + Megatron-LM \u0906\u0927\u093e\u0930\u093f\u0924 ZBPP \u090f\u0915\u094d\u0938\u091f\u0947\u0902\u0936\u0928 | NVTX \u090f\u0928\u094b\u091f\u0947\u0936\u0928\u094d\u0938 \u0914\u0930 \u0915\u0938\u094d\u091f\u092e\u093e\u0907\u091c\u093c\u094d\u0921 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u0930 |\n\n---\n\n## 3. \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u0915\u093e\u0930\u0915 \u0914\u0930 \u091a\u0930 (Experimental Variables & Controls)\n\n### 3.1 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u091a\u0930 (Independent Variables)\n1. **\u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u093f\u0902\u0917 \u0935\u093f\u0927\u093f**:\n   - `1F1B`: \u092e\u093e\u0928\u0915 Megatron-LM \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u093f\u0902\u0917\u0964\n   - `1F1B-I`: \u0907\u0902\u091f\u0930\u0932\u0940\u0935\u094d\u0921 1F1B ($v=2$ \u091a\u0902\u0915\u094d\u0938 \u092a\u094d\u0930\u0924\u093f GPU)\u0964\n   - `ZB-1p`: 1 \u091a\u0902\u0915 \u092a\u094d\u0930\u0924\u093f GPU, $B$ \u0914\u0930 $W$ \u0938\u094d\u092a\u094d\u0932\u093f\u091f \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u093f\u0902\u0917\u0964\n   - `ZB-2p`: 2 \u091a\u0902\u0915\u094d\u0938 \u092a\u094d\u0930\u0924\u093f GPU, $B$ \u0914\u0930 $W$ \u0938\u094d\u092a\u094d\u0932\u093f\u091f \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u093f\u0902\u0917 (\u091c\u093c\u0940\u0930\u094b \u092c\u092c\u0932 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u0930)\u0964\n2. **\u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e ($m$)**:\n   - \u092e\u093e\u0928: $m \\in \\{4, 8, 12, 16, 24, 32, 48, 64\\}$\n   - \u092f\u0939 \u0936\u094d\u0930\u0947\u0923\u0940 $m < p$ (\u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u092c\u092c\u0932), $m = p$ (\u0915\u094d\u0930\u093e\u0902\u0924\u093f\u0915 \u092c\u093f\u0902\u0926\u0941), \u0914\u0930 $m \\gg p$ (\u090f\u0938\u093f\u092e\u094d\u091f\u094b\u091f\u093f\u0915 \u0925\u094d\u0930\u0942\u092a\u0941\u091f) \u0915\u094b \u0915\u0935\u0930 \u0915\u0930\u0924\u0940 \u0939\u0948\u0964\n\n### 3.2 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u093f\u0924 \u091a\u0930 (Controlled Variables)\n- **\u0938\u092e\u093e\u0928 \u0932\u0947\u092f\u0930 \u0935\u093f\u092d\u093e\u091c\u0928 (Layer Balance)**:\n  - 1-\u092a\u093e\u0930\u094d\u091f\u0940\u0936\u0928 \u0935\u093f\u0927\u093f\u092f\u094b\u0902 (`1F1B`, `ZB-1p`): \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 GPU \u092a\u0930 4 \u0932\u0947\u092f\u0930\u094d\u0938 ($32 / 8 = 4$)\u0964\n  - 2-\u092a\u093e\u0930\u094d\u091f\u0940\u0936\u0928 \u0935\u093f\u0927\u093f\u092f\u094b\u0902 (`1F1B-I`, `ZB-2p`): \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 GPU \u092a\u0930 2 \u0935\u0930\u094d\u091a\u0941\u0905\u0932 \u091a\u0902\u0915\u094d\u0938, \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092e\u0947\u0902 2 \u0932\u0947\u092f\u0930\u094d\u0938 ($2 \\times 2 = 4$ \u0932\u0947\u092f\u0930\u094d\u0938 \u092a\u094d\u0930\u0924\u093f GPU)\u0964\n- **\u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0932\u094b\u0921 \u090f\u0935\u0902 \u092b\u094d\u0932\u094b\u092a\u094d\u0938**: \u0938\u093f\u0902\u0925\u0947\u091f\u093f\u0915 \u091f\u094b\u0915\u0928 \u0907\u0928\u092a\u0941\u091f \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 \u092a\u0948\u0921\u093f\u0902\u0917 \u0915\u0947 \u0905\u0902\u0924\u0930 \u0915\u094b \u0938\u092e\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u093e\u0964\n- **GPU \u0915\u094d\u0932\u0949\u0915 \u092b\u094d\u0930\u0940\u0915\u094d\u0935\u0947\u0902\u0938\u0940**: \u0925\u094d\u0930\u0949\u091f\u0932\u093f\u0902\u0917 \u0914\u0930 \u0915\u094d\u0932\u0949\u0915 \u0921\u094d\u0930\u093f\u092b\u094d\u091f \u0915\u094b \u0930\u094b\u0915\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f `nvidia-smi -ac` \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u0915\u094d\u0932\u0949\u0915 \u0915\u094b \u0932\u0949\u0915 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n---\n\n## 4. \u0906\u0936\u094d\u0930\u093f\u0924 \u091a\u0930 \u090f\u0935\u0902 \u092e\u093e\u092a\u0928 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 (Dependent Variables & Evaluation Metrics)\n\n1. **\u0938\u093f\u0938\u094d\u091f\u092e \u0925\u094d\u0930\u0942\u092a\u0941\u091f (Throughput)**:\n   - **Tokens Per Second (TPS)**:\n     $$\\text{TPS} = \\frac{m \\times b \\times s}{T_{\\text{iter}}}$$\n   - **Model FLOPs Utilization (MFU)**: \u0939\u093e\u0930\u094d\u0921\u0935\u0947\u092f\u0930 \u0915\u0940 \u092a\u0940\u0915 \u0915\u094d\u0937\u092e\u0924\u093e \u0915\u0947 \u0938\u093e\u092a\u0947\u0915\u094d\u0937 \u0917\u0923\u0928\u093e \u0926\u0915\u094d\u0937\u0924\u093e\u0964\n2. **\u092e\u093e\u092a\u093e \u0917\u092f\u093e \u092c\u092c\u0932 \u0905\u0928\u0941\u092a\u093e\u0924 (Measured Bubble Rate)**:\n   $$\\text{Bubble Rate}_{\\text{measured}} = 1 - \\frac{\\sum_{i=1}^m (T_{F,i} + T_{B,i} + T_{W,i})}{p \\times T_{\\text{iter}}}$$\n3. **\u092a\u0940\u0915 \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0928 \u092e\u0947\u092e\u094b\u0930\u0940 (Peak Memory)**:\n   - `torch.cuda.max_memory_allocated()` \u0926\u094d\u0935\u093e\u0930\u093e \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 GPU \u092a\u0930 \u0905\u0927\u093f\u0915\u0924\u092e \u092e\u0947\u092e\u094b\u0930\u0940 \u0909\u092a\u092f\u094b\u0917 \u0915\u093e \u092e\u093e\u092a\u0928\u0964\n\n---\n\n## 5. \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u090f\u0935\u0902 \u092e\u093e\u092a\u0928 \u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 (Execution & Measurement Protocol)\n\n1. **\u0935\u093e\u0930\u094d\u092e-\u0905\u092a \u091a\u0930\u0923 (Warm-up Phase)**:\n   - \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0915\u0949\u0928\u094d\u092b\u093c\u093f\u0917\u0930\u0947\u0936\u0928 $(Schedule, m)$ \u0915\u0947 \u0932\u093f\u090f \u092a\u0939\u0932\u0947 10 \u0938\u094d\u091f\u0947\u092a\u094d\u0938 \u091a\u0932\u093e\u090f \u091c\u093e\u090f\u0902\u0917\u0947 \u0924\u093e\u0915\u093f PyTorch \u092e\u0947\u092e\u094b\u0930\u0940 \u090f\u0932\u094b\u0915\u0947\u091f\u0930, \u0915\u0930\u094d\u0928\u0932 \u0915\u0902\u092a\u093e\u0907\u0932\u0947\u0936\u0928, \u0914\u0930 CUDA \u0917\u094d\u0930\u093e\u092b\u094d\u0938 \u0938\u094d\u0925\u093f\u0930 \u0939\u094b \u091c\u093e\u090f\u0902\u0964\n2. **\u092e\u093e\u092a\u0928 \u091a\u0930\u0923 (Measurement Phase)**:\n   - 40 \u0938\u094d\u0925\u093f\u0930 (steady-state) \u0907\u091f\u0930\u0947\u0936\u0928\u094d\u0938 \u0915\u093e \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928\u0964\n   - \u0938\u092e\u092f \u0915\u093e \u0938\u091f\u0940\u0915 \u092e\u093e\u092a\u0928 CPU \u0918\u0921\u093c\u093f\u092f\u094b\u0902 \u0915\u0947 \u092c\u091c\u093e\u092f \u0939\u093e\u0930\u094d\u0921\u0935\u0947\u092f\u0930 `cudaEventElapsedTime` \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n3. **NVTX \u092a\u094d\u0930\u094b\u092b\u093e\u0907\u0932\u093f\u0902\u0917 \u091a\u0930\u0923**:\n   - 3 \u0907\u091f\u0930\u0947\u0936\u0928\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f Nsight Systems \u091f\u094d\u0930\u0947\u0938 \u090f\u0915\u0924\u094d\u0930\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e, \u091c\u093f\u0938\u092e\u0947\u0902 $F$, $B$, $W$ \u0915\u0930\u094d\u0928\u0932\u094d\u0938 \u0914\u0930 P2P \u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u0907\u0935\u0947\u0902\u091f\u094d\u0938 \u0915\u094b NVTX \u0938\u0947 \u091a\u093f\u0939\u094d\u0928\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e \u0924\u093e\u0915\u093f \u092c\u092c\u0932 (GPU \u0906\u0907\u0921\u0932 \u0938\u092e\u092f) \u0915\u094b \u0935\u093f\u091c\u093c\u0941\u0905\u0932\u093e\u0907\u091c\u093c \u0914\u0930 \u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0947\u0964\n4. **\u092a\u0941\u0928\u0930\u093e\u0935\u0943\u0924\u094d\u0924\u093f \u090f\u0935\u0902 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940**:\n   - \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0930\u0928 \u0915\u094b 3 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u091f\u094d\u0930\u093e\u092f\u0932\u094d\u0938 (trias) \u092e\u0947\u0902 \u0926\u094b\u0939\u0930\u093e\u092f\u093e \u091c\u093e\u090f\u0917\u093e \u0914\u0930 95% \u0935\u093f\u0936\u094d\u0935\u093e\u0938 \u0905\u0902\u0924\u0930\u093e\u0932 (Confidence Interval) \u0915\u0940 \u0917\u0923\u0928\u093e \u0915\u0940 \u091c\u093e\u090f\u0917\u0940\u0964\n\n---\n\n## 6. \u0921\u0947\u091f\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u090f\u0935\u0902 \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u092f\u094b\u091c\u0928\u093e (Data Analysis & Hypothesis Validation Plan)\n\n### 6.1 \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u092c\u0928\u093e\u092e \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a \u0915\u0930\u094d\u0935 (Scaling Curve Analysis)\n\u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0935\u093f\u0927\u093f \u0915\u0947 \u0932\u093f\u090f $m$ \u0915\u0947 \u092b\u0932\u0928 \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0925\u094d\u0930\u0942\u092a\u0941\u091f $\\text{TPS}(m)$ \u0915\u094b \u092a\u094d\u0932\u0949\u091f \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e:\n- **1F1B, 1F1B-I, ZB-1p \u0915\u0947 \u0932\u093f\u090f**:\n  - \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u0935\u0915\u094d\u0930 \u092e\u0947\u0902 $m=8$ \u0938\u0947 $m=64$ \u0915\u0940 \u0913\u0930 \u090f\u0915 \u0924\u0940\u0935\u094d\u0930 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0922\u0932\u093e\u0928 ($\\frac{d\\,\\text{TPS}}{dm} > 0$) \u0926\u0947\u0916\u093e \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964\n  - \u0915\u092e $m$ ($m=8$) \u092a\u0930 \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u0909\u0928\u0915\u0947 \u0905\u0927\u093f\u0915\u0924\u092e \u0925\u094d\u0930\u0942\u092a\u0941\u091f ($m=64$) \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0915\u093e\u092b\u0940 \u0915\u092e (\u0909\u0926\u093e\u0939\u0930\u0923\u093e\u0930\u094d\u0925, 1F1B \u092e\u0947\u0902 $< 50\\%$) \u0939\u094b\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964\n- **ZB-2p \u0915\u0947 \u0932\u093f\u090f**:\n  - $m=8$ ($m=p$) \u092a\u0930 \u0939\u0940 ZB-2p \u0915\u093e \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u0905\u092a\u0928\u0947 \u0905\u0927\u093f\u0915\u0924\u092e \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u0915\u0947 $\\ge 90\\%$ \u0924\u0915 \u092a\u0939\u0941\u0902\u091a \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964\n  - $m$ \u0915\u094b 8 \u0938\u0947 \u092c\u0922\u093c\u093e\u0915\u0930 64 \u0915\u0930\u0928\u0947 \u092a\u0930 ZB-2p \u0915\u0947 \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u092e\u0947\u0902 \u0928\u094d\u092f\u0942\u0928\u0924\u092e \u092c\u0926\u0932\u093e\u0935 (\u092b\u094d\u0932\u0948\u091f \u0915\u0930\u094d\u0935) \u0939\u094b\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964\n\n### 6.2 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u092a\u0930\u0940\u0915\u094d\u0937\u0923 (Statistical Tests)\n- **\u0915\u092e \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a \u0936\u093e\u0938\u0928 ($m=8$) \u092e\u0947\u0902 \u0924\u0941\u0932\u0928\u093e**:\n  - \u0935\u0928-\u0935\u0947 ANOVA \u0914\u0930 Tukey HSD \u092a\u094b\u0938\u094d\u091f-\u0939\u0949\u0915 \u091f\u0947\u0938\u094d\u091f:\n    $$\\text{TPS}_{ZB\\text{-}2p}(m=8) \\gg \\text{TPS}_{ZB\\text{-}1p}(m=8) > \\text{TPS}_{1F1B\\text{-}I}(m=8) > \\text{TPS}_{1F1B}(m=8)$$\n  - \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0938\u093e\u0930\u094d\u0925\u0915\u0924\u093e \u0938\u094d\u0924\u0930 $p < 0.01$ \u092a\u0930 \u091c\u093e\u0902\u091a\u0940 \u091c\u093e\u090f\u0917\u0940\u0964\n- **\u0938\u093e\u092a\u0947\u0915\u094d\u0937 \u0938\u0941\u0927\u093e\u0930 \u0905\u0928\u0941\u092a\u093e\u0924 (Scaling Ratio)**:\n  $$R_{\\text{scale}} = \\frac{\\text{TPS}(m=64)}{\\text{TPS}(m=8)}$$\n  - \u092f\u0926\u093f \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e \u0938\u0924\u094d\u092f \u0939\u0948, \u0924\u094b:\n    $$R_{\\text{scale}}(1F1B) \\approx 1.8 - 2.0$$\n    $$R_{\\text{scale}}(1F1B\\text{-}I) \\approx 1.4 - 1.6$$\n    $$R_{\\text{scale}}(ZB\\text{-}1p) \\approx 1.2 - 1.4$$\n    $$R_{\\text{scale}}(ZB\\text{-}2p) \\approx 1.0 - 1.05$$\n\n---\n\n## 7. \u0938\u0902\u092d\u093e\u0935\u093f\u0924 \u091a\u0941\u0928\u094c\u0924\u093f\u092f\u093e\u0901, \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u090f\u0935\u0902 \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u094d\u092f\u0924\u093e (Feasibility, Risks & Controls)\n\n1. **\u092e\u0947\u092e\u094b\u0930\u0940 \u0938\u0940\u092e\u093e \u0914\u0930 OOM (Out-of-Memory)**:\n   - *\u091c\u094b\u0916\u093f\u092e*: \u092c\u0921\u093c\u0947 $m$ ($m=64$) \u092f\u093e ZB-2p \u0915\u0947 2-\u092a\u093e\u0930\u094d\u091f\u0940\u0936\u0928 \u0936\u0947\u0921\u094d\u092f\u0942\u0932 \u092e\u0947\u0902 \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0928 \u092e\u0947\u092e\u094b\u0930\u0940 \u0905\u0927\u093f\u0915 \u0939\u094b \u0938\u0915\u0924\u0940 \u0939\u0948\u0964\n   - *\u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923*: \u092f\u0926\u093f \u092e\u0947\u092e\u094b\u0930\u0940 80GB \u0938\u0947 \u0905\u0927\u093f\u0915 \u0939\u094b\u0928\u0947 \u0915\u093e \u091c\u094b\u0916\u093f\u092e \u0939\u094b, \u0924\u094b \u0938\u092d\u0940 \u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u090f\u0915\u0938\u092e\u093e\u0928 \u0930\u0942\u092a \u0938\u0947 \u0938\u093f\u0932\u0947\u0915\u094d\u091f\u093f\u0935 \u090f\u0915\u094d\u091f\u093f\u0935\u0947\u0936\u0928 \u091a\u0947\u0915\u092a\u0949\u0907\u0902\u091f\u093f\u0902\u0917 (Activation Checkpointing) \u0932\u093e\u0917\u0942 \u0915\u0940 \u091c\u093e\u090f\u0917\u0940\u0964\n2. **$B$ \u0914\u0930 $W$ \u0915\u0930\u094d\u0928\u0932 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u0915\u093e \u0938\u0902\u0924\u0941\u0932\u0928**:\n   - *\u0938\u0924\u094d\u092f\u093e\u092a\u0928*: ZB \u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u0915\u0940 \u092a\u094d\u0930\u092d\u093e\u0935\u0936\u0940\u0932\u0924\u093e \u0907\u0938 \u092c\u093e\u0924 \u092a\u0930 \u0928\u093f\u0930\u094d\u092d\u0930 \u0915\u0930\u0924\u0940 \u0939\u0948 \u0915\u093f \u092c\u0948\u0915\u0935\u0930\u094d\u0921 \u092a\u093e\u0938 \u092e\u0947\u0902 $T_B$ \u0914\u0930 $T_W$ \u0915\u093e \u0905\u0928\u0941\u092a\u093e\u0924 \u0938\u0941\u0938\u0902\u0917\u0924 \u0939\u094b\u0964 \u090f\u0915\u0932 \u0932\u0947\u092f\u0930 \u0915\u0940 \u0905\u0932\u0917 \u0938\u0947 \u092a\u094d\u0930\u094b\u092b\u093e\u0907\u0932\u093f\u0902\u0917 \u0915\u0930\u0915\u0947 \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0940 \u091c\u093e\u090f\u0917\u0940 \u0915\u093f $T_F \\approx T_B \\approx T_W$ \u0915\u093e \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0906\u0927\u093e\u0930 \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u092e\u093e\u0928\u094d\u092f \u0939\u0948\u0964\n3. **\u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u0913\u0935\u0930\u0939\u0947\u0921 \u0915\u093e \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923**:\n   - \u0907\u0902\u091f\u0930\u0932\u0940\u0935\u094d\u0921 \u0914\u0930 2-\u092a\u093e\u0930\u094d\u091f\u0940\u0936\u0928 \u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 P2P \u0938\u0902\u091a\u093e\u0930 \u0915\u0940 \u0906\u0935\u0943\u0924\u094d\u0924\u093f \u0926\u094b\u0917\u0941\u0928\u0940 \u0939\u094b \u091c\u093e\u0924\u0940 \u0939\u0948\u0964 \u092f\u0939 \u0938\u0941\u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u093f \u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u0924\u0941\u0932\u0928\u093e \u0915\u094b \u0935\u093f\u0915\u0943\u0924 \u0928 \u0915\u0930\u0947, \u0915\u0930\u094d\u0928\u0932-\u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u0913\u0935\u0930\u0932\u0948\u092a (Non-blocking P2P sends/receives) \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n---\n\n## 8. \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937 (Expected Outcome)\n\u092f\u0939 \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0938\u091f\u0940\u0915, \u0928\u093f\u0937\u094d\u092a\u0915\u094d\u0937 \u0914\u0930 \u092a\u0930\u093f\u092e\u093e\u0923\u093e\u0924\u094d\u092e\u0915 \u0930\u0942\u092a \u0938\u0947 \u092f\u0939 \u0938\u093f\u0926\u094d\u0927 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0938\u0915\u094d\u0937\u092e \u0939\u0948 \u0915\u093f \u0915\u094d\u092f\u093e 1F1B, 1F1B-I, \u0914\u0930 ZB-1p \u092e\u0947\u0902 \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a \u092c\u0922\u093c\u093e\u0928\u0947 \u092a\u0930 \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u092e\u0947\u0902 \u0932\u0917\u093e\u0924\u093e\u0930 \u0938\u0941\u0927\u093e\u0930 \u0939\u094b\u0924\u093e \u0939\u0948, \u0914\u0930 \u0915\u094d\u092f\u093e ZB-2p \u0915\u092e \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u092c\u0948\u091a \u0939\u094b\u0928\u0947 \u092a\u0930 \u092d\u0940 \u092c\u092c\u0932-\u092e\u0941\u0915\u094d\u0924 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u093f\u0902\u0917 \u0915\u0947 \u0915\u093e\u0930\u0923 \u0909\u091a\u094d\u091a \u0925\u094d\u0930\u0942\u092a\u0941\u091f \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u0947 \u092e\u0947\u0902 \u0938\u092b\u0932 \u0930\u0939\u0924\u093e \u0939\u0948\u0964", "assumptions": ["\u092e\u0949\u0921\u0932 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930 (GPT 7B) \u0915\u0947 \u0938\u092d\u0940 32 \u0932\u0947\u092f\u0930\u094d\u0938 \u0915\u093e \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0935\u0930\u094d\u0915\u0932\u094b\u0921 \u090f\u0915\u0938\u092e\u093e\u0928 \u0939\u0948, \u091c\u093f\u0938\u0938\u0947 \u0932\u0947\u092f\u0930 \u0935\u093f\u092d\u093e\u091c\u0928 \u0938\u0902\u0924\u0941\u0932\u093f\u0924 \u0930\u0939\u0924\u093e \u0939\u0948\u0964", "\u0915\u092e\u094d\u092f\u0942\u0928\u093f\u0915\u0947\u0936\u0928 \u0914\u0930 \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928 \u0915\u0930\u094d\u0928\u0932\u094d\u0938 \u0928\u0949\u0928-\u092c\u094d\u0932\u0949\u0915\u093f\u0902\u0917 P2P \u092a\u094d\u0930\u093f\u092e\u093f\u091f\u093f\u0935\u094d\u0938 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902, \u091c\u093f\u0938\u0938\u0947 \u0936\u0947\u0921\u094d\u092f\u0942\u0932\u0930 \u092c\u092c\u0932 \u0915\u093e \u092a\u094d\u0930\u092d\u093e\u0935 \u0936\u0941\u0926\u094d\u0927 \u0930\u0942\u092a \u0938\u0947 \u092e\u093e\u092a\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964", "GPU \u092e\u0947\u092e\u094b\u0930\u0940 80GB \u092a\u094d\u0930\u0924\u093f \u0921\u093f\u0935\u093e\u0907\u0938 \u0939\u094b\u0928\u0947 \u0915\u0947 \u0915\u093e\u0930\u0923 b=1 \u0914\u0930 m=64 \u0924\u0915 OOM \u0915\u0940 \u0938\u092e\u0938\u094d\u092f\u093e \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u0928\u0939\u0940\u0902 \u0939\u094b\u0917\u0940\u0964"], "uncertainties": ["\u0939\u093e\u0930\u094d\u0921\u0935\u0947\u092f\u0930 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930 (A100 \u092c\u0928\u093e\u092e H100) \u0915\u0947 \u0906\u0927\u093e\u0930 \u092a\u0930 B \u0914\u0930 W \u0915\u0930\u094d\u0928\u0932\u094d\u0938 \u0915\u0947 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u0938\u092e\u092f \u0915\u093e \u0938\u091f\u0940\u0915 \u0905\u0928\u0941\u092a\u093e\u0924 T_B : T_W \u0925\u094b\u0921\u093c\u093e \u092d\u093f\u0928\u094d\u0928 \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948\u0964"], "stage": "result", "evidence": "\u091f\u093e\u0938\u094d\u0915 \u0930\u093f\u092a\u0949\u091c\u093f\u091f\u0930\u0940 \u092e\u0947\u0902 \u0938\u094d\u0925\u093f\u0924 `task.json` (\u0924\u0925\u093e `track.md`) \u0938\u094d\u092a\u0937\u094d\u091f \u0915\u0930\u0924\u093e \u0939\u0948 \u0915\u093f \u092f\u0939 \u090f\u0915 \u0921\u093f\u091c\u093c\u093e\u0907\u0928-\u0913\u0928\u0932\u0940 \u0915\u093e\u0930\u094d\u092f \u0939\u0948\u0964 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u092a\u0948\u0930\u0947\u0932\u0932\u093f\u091c\u094d\u092e \u0915\u0947 \u0938\u0948\u092